import{_ as i,o as a,c as s,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/klassenunterrichte-anlegen.jpg",u="/bilder/unterricht-kataloge/stundentafel-zuweisen.jpg",d="/bilder/unterricht-kataloge/klassenunterricht-bearbeiten.jpg",S=JSON.parse('{"title":"Klassenunterricht mit Stundentafeln anlegen","description":"","frontmatter":{"title":"Klassenunterricht mit Stundentafeln anlegen","source_pageid":291,"source_revision":5509},"headers":[],"relativePath":"schild3/unterricht-kataloge/klassenunterrichte-anlegen-tutorial.md","filePath":"schild3/unterricht-kataloge/klassenunterrichte-anlegen-tutorial.md"}'),h={name:"schild3/unterricht-kataloge/klassenunterrichte-anlegen-tutorial.md"};function o(c,r,g,p,m,f){return a(),s("div",null,[...r[0]||(r[0]=[t('<h1 id="klassenunterricht-mit-stundentafeln-anlegen" tabindex="-1">Klassenunterricht mit Stundentafeln anlegen <a class="header-anchor" href="#klassenunterricht-mit-stundentafeln-anlegen" aria-label="Permalink to &quot;Klassenunterricht mit Stundentafeln anlegen&quot;">​</a></h1><p>Bereiten Sie Klassenunterricht über Stundentafeln vor und weisen Sie die Fächer den Schülerinnen und Schülern zu. Ergänzen Sie danach die noch fehlenden Angaben.</p><h2 id="_1-definieren-der-unterrichte-uber-stundentafeln" tabindex="-1">1. Definieren der Unterrichte über Stundentafeln <a class="header-anchor" href="#_1-definieren-der-unterrichte-uber-stundentafeln" aria-label="Permalink to &quot;1. Definieren der Unterrichte über Stundentafeln&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/klassenunterrichte-anlegen.jpg"><img src="'+l+'" alt="Klassenunterriuchte lassen sich über Kataloge ➜ Stundentafeln als Vorlagen für Klassen und Jahrgänge anlegen." loading="lazy"></a></p><p><em>Klassenunterriuchte lassen sich über Kataloge ➜ <strong>Stundentafeln</strong> als Vorlagen für Klassen und Jahrgänge anlegen.</em></p><p><strong>Klassenunterricht</strong> findet gemeinsam mit der gesamten Klasse statt. Die vorgesehenen Fächer und Unterrichtszeiten werden in einer Stundentafel zusammengefasst.</p><p>Dieser wird in SchILD-NRW mit der <em>Kursart</em> PUK, also &quot;Pflichtunterricht im Klassenverband&quot;, bezeichnet. Jeglicher anderer Unterricht ist <em>Kursunterricht</em>, das heißt, es werden nur Teile der Klasse, nicht alle Schülerinnen und Schüler der Klasse gemeinsam, unterrichtet.</p><p>Öffnen Sie <strong>Kataloge → Stundentafel</strong>.</p><p>Legen Sie eine <strong>Stundentafel</strong> mit den vorgesehenen Fächern und Unterrichtsstunden an. Sie kann für einen ganzen Jahrgang oder für einzelne Klassen gelten. So müssen Sie den regelmäßigen Unterricht nicht für jede Person einzeln erfassen.</p><p>Geben Sie einer Stundentafel einen sprechenden Namen, etwa nach dem Jahrgang, dem sie zugeordnet werden soll.</p><p>Für eine Stundentafel werden das <strong>Fach</strong> und die <strong>WZE</strong>, die Wochenzeitzeiteinheiten angegeben. Hier werden die Schulstunden im Zeitraster der Schule beziehungsweise die Minuten im Minutenmodell eingegeben.</p><p>Die <strong>Kursart</strong> ist natürlich PUK.</p><p>Schlussendlich ist noch anzuhaken, ob es sich bei dem Fach um <strong>Epochenunterricht</strong> handelt.</p><p>Diese Stundentafel ist eine Auflistung aller PUK-Unterrichte, welche die Klasse gemeinsam erhält.</p><p>Kursunterrichte werden gesondert eingeteilt.</p><p>Diese Stundentafeln bleiben bestehen, solange sich der Unterricht bzw. die Fächer im Jahrgang nicht ändern. Eventuell müssen hier immer wieder Anpassungen erfolgen.</p><h2 id="_2-zuweisung-der-stundentafeln" tabindex="-1">2. Zuweisung der Stundentafeln <a class="header-anchor" href="#_2-zuweisung-der-stundentafeln" aria-label="Permalink to &quot;2. Zuweisung der Stundentafeln&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/stundentafel-zuweisen.jpg"><img src="'+u+'" alt="Zuweisung von &quot;Fächern&quot; per Gruppenprozess &quot;Stundentafel zuweisen&quot;." loading="lazy"></a></p><p><em>Zuweisung von &quot;Fächern&quot; per Gruppenprozess &quot;Stundentafel zuweisen&quot;.</em></p><p>Um die Klassenunterrichte den Schülern zuzuweisen wird der <em>Gruppenprozesse ➜ Fächer</em> ➜ <strong>Stundentafeln zuweisen</strong> verwendet.</p><p>Filtern Sie die Schülerauswahl auf den gewünschten Jahrgang oder auf einzelne Klassen.</p>',21),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("An Grundschulen können Kinder verschiedener Jahrgänge gemeinsam eine Klasse besuchen. Die Jahrgänge "),e("strong",null,"01 und 02"),n(" sind von den zusätzlichen "),e("strong",null,"EP-Jahren E1, E2 und E3"),n(" zu unterscheiden. Prüfen Sie für die Stundentafel die tatsächlichen Jahrgänge und den Unterrichtsbedarf der ausgewählten Kinder.")])],-1),t('<p>Im Fenster des Gruppenprozesses wird nun der die passende Stundentafel ausgewählt, etwa die für den Jahrgang angelegte. Mit <code>Übernehmen</code> wird diese Stundentafel mit den PUK-Fächern nun den ausgewählten Schülern zugewiesen.</p><p>Entfernen Sie die Häkchen bei Fächern, die bei diesem Vorgang nicht bearbeitet werden sollen. Wenn Sie den Löschmodus verwenden, bleiben nur die Häkchen der Fächer gesetzt, die bei der ausgewählten Schülergruppe gelöscht werden sollen.</p><p>Dafür müssen dann die zu löschenden Fächer angehakt bleiben und unten dem Haken bei <em>Ausgewählte Fächer beim Schüler löschen</em> angehakt sein.</p><h2 id="_3-vervollstandigen-der-facher" tabindex="-1">3. Vervollständigen der Fächer <a class="header-anchor" href="#_3-vervollstandigen-der-facher" aria-label="Permalink to &quot;3. Vervollständigen der Fächer&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/klassenunterricht-bearbeiten.jpg"><img src="'+d+'" alt="&quot;Klassenunterrichte bearbeiten&quot; per Gruppenprozess." loading="lazy"></a></p><p><em>&quot;Klassenunterrichte bearbeiten&quot; per Gruppenprozess.</em></p><p>Es folgt nun das Eintragen der jeweiligen Fachlehrkraft zu den Fächern.</p><p>Dies erfolgt über den Gruppenprozess <strong>Klassenunterrichte bearbeiten</strong>.</p><p>Hier können Sie auch die Unterrichtszeit anpassen. Beispiel: Im neuen Halbjahr sinkt die Stundenzahl in Geschichte von zwei auf eine, während sie in Erdkunde von einer auf zwei steigt.</p>',9),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Sollten nun noch Veränderungen vorgenommen werden müssen, dann geschieht dies über den "),e("em",null,"Gruppenprozess ➜ Details zu Fächern bei Schülern ändern"),n(". Hier können verschiedenste Änderungen erfolgen, Zusatzkräfte hinzu gefügt oder auch Einstellungen in Form von "),e("em",null,"Epochalunterricht"),n(", "),e("em",null,"Unterricht nicht aufs Zeugnis"),n(" oder auch "),e("em",null,"fachbezogene Bemerkungen"),n(" für die Gesamtheit der Schülerinnen und Schüler angepasst werden.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Klassenunterrichte_anlegen_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5509.")],-1)])])}const k=i(h,[["render",o]]);export{S as __pageData,k as default};
